// Yalnızca önceden üretilmiş JSON okunur; tıklama AI analizi veya toplama başlatmaz.
const sections={turkiye:['Türkiye Gündemi','Siyaset, Meclis ve ekonomi politikalarından öne çıkan gelişmeler.'],dunya:['Dünya Gündemi','Uluslararası siyasetin ve diplomasinin öne çıkan haberleri.'],zafer:['Zafer Partisi','Açıklamalar, faaliyetler, eleştiriler ve iddialar; kaynaklarıyla birlikte.'],ozel:['Özel Takip','Mehmet Harun Yüksel, Fazılcan Yurt ve Akın Köstemir hakkında haberler.']};
let category='turkiye',bulletin=null,index=null,selected='',requestId=0;
const $=id=>document.getElementById(id),fmt=d=>new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',dateStyle:'medium',timeStyle:'short'}).format(new Date(d));
const trDate=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function el(tag,text,cls){const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n}
function link(url,text,cls){const a=el('a',text,cls);try{const u=new URL(url);if(!['https:','http:'].includes(u.protocol))return el('span',text);a.href=u.href;a.target='_blank';a.rel='noopener noreferrer'}catch{return el('span',text)}return a}
function setCategory(cat){category=cat;document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.cat===cat);b.setAttribute('aria-pressed',String(b.dataset.cat===cat))});$('heading').textContent=sections[cat][0];$('description').textContent=sections[cat][1];$('sectionNo').textContent='0'+(Object.keys(sections).indexOf(cat)+1);render()}
function days(){const box=$('days');box.replaceChildren();const today=trDate();for(let i=0;i<7;i++){const d=new Date(today+'T12:00:00+03:00');d.setUTCDate(d.getUTCDate()-i);const date=d.toISOString().slice(0,10);const b=el('button',i===0?'Bugün':i===1?'Dün':new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'short',timeZone:'Europe/Istanbul'}).format(d));b.classList.toggle('selected',date===selected);b.onclick=()=>load(date);box.append(b)}}
function render(){const cards=$('cards');cards.replaceChildren();const q=$('search').value.toLocaleLowerCase('tr');const items=(bulletin?.items||[]).filter(n=>n.categories.includes(category)&&(!q||(n.title+' '+n.summary+' '+n.source).toLocaleLowerCase('tr').includes(q)));$('count').textContent=items.length+' HABER · '+sections[category][0].toLocaleUpperCase('tr');if(!items.length){cards.append(el('div',bulletin?'Bu bölümde bu tarihe ait eşleşen haber bulunamadı.':'Bu tarih için hazırlanmış bülten bulunmuyor. Arşivden başka bir gün seçebilirsiniz.','empty'));return}for(const n of items){const card=el('article',null,'card'),thumb=el('div',null,'thumbnail'),placeholder=el('div','ST','placeholder');placeholder.append(el('small','GÜNDEM'));thumb.append(placeholder);if(n.image){const img=el('img');img.alt='';img.loading='lazy';img.referrerPolicy='no-referrer';try{if(['http:','https:'].includes(new URL(n.image).protocol)){img.src=n.image;img.onerror=()=>img.remove();thumb.append(img);img.style.position='absolute'}}catch{}}card.append(thumb);const body=el('div');body.append(el('p',sections[category][0].toLocaleUpperCase('tr'),'kicker'));const h=el('h2');h.append(link(n.url,n.title));body.append(h);body.append(el('p',n.summary||'RSS akışı bu haber için özet metni sağlamadı. Ayrıntıları orijinal kaynaktan okuyabilirsiniz.','summary'));if(n.summaryLimited)body.append(el('p','Kaynak metni sınırlı · 3–4 cümlelik özet üretilemedi.','limited'));const meta=el('div',null,'meta');meta.append(el('span',n.source),el('span','·'));const t=el('time',fmt(n.published));t.dateTime=n.published;meta.append(t,link(n.url,'Habere git ↗','read'));body.append(meta);if(n.sources.length>1){const s=el('details',null,'sources');s.append(el('summary',n.sources.length+' kaynakta benzer haber'));n.sources.forEach(v=>s.append(link(v.url,v.name)));body.append(s)}if(n.xUrl)body.append(link(n.xUrl,'X paylaşımını aç ↗'));card.append(body);cards.append(card)}}
async function load(date){const id=++requestId;selected=date;$('archive').value=date;days();$('notice').textContent='';bulletin=null;$('cards').replaceChildren(el('p','Bülten yükleniyor…','empty'));try{const response=await fetch('data/'+date+'.json',{cache:'no-cache'});if(!response.ok)throw Error('missing');const data=await response.json();if(id!==requestId)return;bulletin=data;$('updated').textContent='Son derleme · '+fmt(data.updatedAt);const failed=data.feeds.filter(f=>!f.ok).length;$('notice').textContent=(date===trDate()?'':'Arşiv bülteni · '+date+'. ')+(failed?failed+' akışa erişilemedi; erişilebilen kaynaklar gösteriliyor.':'');$('health').replaceChildren(...data.feeds.map(f=>{const p=el('p');p.append(link(f.url,(f.ok?'✓ ':'! ')+f.name));return p}))}catch{if(id!==requestId)return;$('updated').textContent='Bu tarih için bülten yok';$('notice').textContent=date===trDate()?'Günün bülteni henüz hazır değil. Planlanan toplama saati 13.00 TSİ.':'Bu tarihte arşiv kaydı bulunmuyor.';$('health').textContent='Bu güne ait kaynak raporu yok.'}render()}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>setCategory(b.dataset.cat));$('search').oninput=render;$('archive').onchange=e=>{if(e.target.value)load(e.target.value)};$('follow').onclick=()=>{setCategory('ozel');$('heading').scrollIntoView({behavior:'smooth'})};
(async()=>{$('editionDate').textContent=new Intl.DateTimeFormat('tr-TR',{dateStyle:'full',timeZone:'Europe/Istanbul'}).format(new Date());$('archive').max=trDate();try{const r=await fetch('data/index.json',{cache:'no-cache'});if(!r.ok)throw Error();index=await r.json();await load(index.latest||trDate());if(index.latest&&index.latest!==trDate())$('notice').textContent='Bugünün bülteni henüz hazır değil. Son mevcut bülten gösteriliyor: '+index.latest+'.'}catch{await load(trDate())}})();

